import { Signer } from "./signer.js";
/**
 * @public
 */
export function getNip07Signer(client) {
    const windowRef = window;
    if (typeof windowRef.nostr === "undefined") {
        return;
    }
    return new Signer(client, windowRef.nostr);
}
